'use strict';

// MODULES //

var tape = require( 'tape' );
var isDataSet = require( '@stdlib/plot/vega/base/assert/is-dataset' );
var array2tidy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof array2tidy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a data set', function test( t ) {
	var out = array2tidy( [ 1, 2, 3 ], 'data', [ 'index', 'value' ] );
	t.strictEqual( isDataSet( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having a specified name', function test( t ) {
	var out = array2tidy( [ 1, 2, 3 ], 'beep', [ 'index', 'value' ] );
	t.strictEqual( out.name, 'beep', 'returns expected value' );
	t.end();
});

tape( 'the function converts an array to a "tidy" data set', function test( t ) {
	var expected;
	var actual;
	var i;

	actual = array2tidy( [ 1, 2, 3 ], 'data', [ 'index', 'value' ] ).toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'index': 0,
			'value': 1
		},
		{
			'index': 1,
			'value': 2
		},
		{
			'index': 2,
			'value': 3
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying field names', function test( t ) {
	var expected;
	var actual;
	var i;

	actual = array2tidy( [ 1, 2 ], 'data', [ 'x', 'y' ] ).toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'x': 0,
			'y': 1
		},
		{
			'x': 1,
			'y': 2
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having no values if provided an empty array', function test( t ) {
	var expected;
	var actual;

	actual = array2tidy( [], 'data', [ 'index', 'value' ] ).toJSON().values;
	expected = [];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
